const DB='chinese-life-v01',STORE='lives';
const validPlayer=s=>s&&s.version===1&&typeof s.id==='string'&&Number.isFinite(s.rng)&&Number.isFinite(s.age)&&['history','parents','children','npcs','properties','scheduled','audit','memories','cityHistory','careerHistory','qualifications','clubs','tags','schoolHistory','socialHistory','debugLogs'].every(k=>Array.isArray(s[k]))&&['stats','hidden','hobbies','personality','investments','totals','counts','world'].every(k=>s[k]&&typeof s[k]==='object')&&['health','intelligence','eq','happiness','reputation'].every(k=>Number.isFinite(s.stats[k]))&&['deposit','fund','stock','venture'].every(k=>Number.isFinite(s.investments[k]))&&(!s.pending||(Array.isArray(s.pending.options)&&s.pending.options.length>=2&&s.frame));
export function validateSave(value){if(!value||value.version!==1||!Array.isArray(value.past)||!Array.isArray(value.unlocked))throw Error('存档格式暂不支持，请保留原存档');if((value.current&&!validPlayer(value.current))||value.past.some(s=>!validPlayer(s))||(value.checkpoint&&!validPlayer(value.checkpoint)))throw Error('人生存档不完整，未覆盖原记录');return value;}
export const emptySave=()=>({version:1,current:null,checkpoint:null,past:[],unlocked:[]});
const open=()=>new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('此浏览器无法使用本地存档'));return;}const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('无法打开本地存档'));r.onblocked=()=>reject(Error('请关闭其他游戏页面后重试'));});
export async function loadSave(){const db=await open();try{return await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readonly'),r=tx.objectStore(STORE).get('save');r.onsuccess=()=>{try{resolve(r.result?validateSave(r.result):emptySave());}catch(e){reject(e);}};r.onerror=()=>reject(Error('无法读取人生存档'));});}finally{db.close();}}
export async function saveGame(value){validateSave(value);const db=await open();try{await new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(structuredClone(value),'save');tx.oncomplete=()=>resolve();tx.onerror=tx.onabort=()=>reject(Error('保存失败，请检查浏览器可用空间后重试'));});}finally{db.close();}}
export function updateSave(save,current,checkpoint=save.checkpoint){const next=structuredClone(save);next.current=current;next.checkpoint=checkpoint;if(current.dead){next.past=next.past.filter(x=>x.id!==current.id);next.past.unshift(structuredClone(current));}else next.past=next.past.filter(x=>x.id!==current.id);next.unlocked=[...new Set([...next.unlocked,...current.tags])];return next;}
export function settings(){try{return {...{largeText:false},...JSON.parse(localStorage.getItem('life-settings')??'{}')};}catch{return {largeText:false};}}
export function setSettings(value){try{localStorage.setItem('life-settings',JSON.stringify(value));}catch{throw Error('设置未能保存，请检查浏览器存储权限');}}
